WITH "m0" AS ( SELECT "s" AS "t0" , "s"."ctid" AS "k0" FROM "public"."mutation_item" AS "s" WHERE false ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ), "w0" AS (SELECT "s" .* FROM "public"."mutation_item" AS "s" WHERE NOT EXISTS ( SELECT 1 FROM "m0" WHERE "m0"."k0" = "s"."ctid" ) UNION ALL SELECT * FROM "r0" ) SELECT json_build_object( 'affected_rows' , (SELECT count(*) FROM "r0" ) )
